function showMessage(message){const text=String(message??'');const box=$('messageBox'),overlay=$('messageDialog');const isError=/تعذر|فشل|خطأ|لا يمكن|غير صالح|ناقص|لا تستخدم|لا يقل|لا تقل|ممتلئة|لم تُحمّل/i.test(text);const isInfo=/تنبيه|ملاحظة|راجع|اكتب|اختر|أدخل/i.test(text);box.className='msg-box'+(isError?' error':isInfo?' info':'');$('messageSymbol').textContent=isError?'!':isInfo?'i':'✓';$('messageTitle').textContent=isError?'تعذر إتمام العملية':isInfo?'مراجعة البيانات':'تمت العملية بنجاح';$('messageText').textContent=text;overlay.classList.add('show');$('messageOk').focus()}
