const LOCALDB='PastryMYLocalDB', LOCALSTORE='appState', BACKUPSTORE='safetyBackups';
function loadState(){return clone(ORIGINAL)}
function localSaveMessage(msg,err=false){const el=$('localSaveStatus');if(el){el.className=err?'autosave err':'autosave';const spans=el.querySelectorAll('span');if(spans[0])spans[0].textContent=err?'!':'●';if(spans[1])spans[1].textContent=msg}}
function openLocalDB(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window)){reject(Error('IndexedDB غير مدعوم'));return}const req=indexedDB.open(LOCALDB,2);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains(LOCALSTORE))req.result.createObjectStore(LOCALSTORE,{keyPath:'id'});if(!req.result.objectStoreNames.contains(BACKUPSTORE))req.result.createObjectStore(BACKUPSTORE,{keyPath:'id'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||Error('تعذر فتح قاعدة الحفظ المحلية'))})}
async function saveSafetyBackup(snapshot,reason){
 const db=await openLocalDB();
 const id='safety-'+Date.now()+'-'+Math.random().toString(16).slice(2);
 const record={id,reason:String(reason||'نسخة أمان'),savedAt:Date.now(),state:clone(snapshot)};
 try{
  await new Promise((resolve,reject)=>{const tx=db.transaction(BACKUPSTORE,'readwrite');tx.objectStore(BACKUPSTORE).put(record);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||Error('تعذر كتابة النسخة الاحتياطية'));tx.onabort=()=>reject(tx.error||Error('تم إلغاء النسخة الاحتياطية'))});
  const check=await new Promise((resolve,reject)=>{const tx=db.transaction(BACKUPSTORE,'readonly');const req=tx.objectStore(BACKUPSTORE).get(id);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error||Error('تعذر التحقق من النسخة الاحتياطية'))});
  if(!check||!check.state||JSON.stringify(check.state)!==JSON.stringify(snapshot))throw new Error('لم تتطابق النسخة الاحتياطية عند التحقق منها.');
  return {id,savedAt:record.savedAt};
 }finally{db.close()}
}
async function saveCriticalState(snapshot,stamp){
 const db=await openLocalDB();
 try{await new Promise((resolve,reject)=>{const tx=db.transaction(LOCALSTORE,'readwrite');tx.objectStore(LOCALSTORE).put({id:KEY,state:clone(snapshot),savedAt:stamp||Date.now()});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||Error('تعذر حفظ الحالة المحلية'));tx.onabort=()=>reject(tx.error||Error('تم إلغاء الحفظ المحلي'))})}finally{db.close()}
}
function normalizedPeriodLabel(v){return String(v||'').normalize('NFKC').trim().toLocaleLowerCase('ar').replace(/[\sـ]+/g,'').replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d))}
function archivePeriodKey(v){
 const n=normalizedPeriodLabel(v);if(/^\d{4}-\d{2}$/.test(n))return n;const yearMatch=n.match(/(19|20|21)\d{2}/),year=yearMatch?yearMatch[0]:'';
 const months=[['يناير',1],['فبراير',2],['مارس',3],['أبريل',4],['ابريل',4],['مايو',5],['يونيو',6],['يونيه',6],['يوليو',7],['يوليه',7],['أغسطس',8],['اغسطس',8],['سبتمبر',9],['أكتوبر',10],['اكتوبر',10],['نوفمبر',11],['ديسمبر',12]];
 if(year){for(const [name,num] of months){if(n.includes(normalizedPeriodLabel(name)))return year+'-'+String(num).padStart(2,'0')}}
 return 'label:'+n;
}
