 const checkNamed=(arr,title,field)=>{(arr||[]).forEach((x,i)=>{if(!String(x[field]||'').trim())errors.push(`${title} رقم ${i+1}: الاسم أو البيان الأساسي ناقص.`)})};
 checkNamed(a.history,'حركة مخزون','name');
