// وحدات الوصفات والمخزون. عوامل التحويل الداخلية: جرام للكتلة، ولتر للحجم.
const UNITS=['جرام','كيلو جرام','لتر','واحدة','بيضة','زجاجة','علبة','ظرف','كيس','عبوة','ملعقة صغيرة','ملعقة كبيرة','رشة','نقطة','كوب','نصف كوب','ربع كوب','وزنة'];
const UNIT_FACTORS={
 'جرام':1,'كيلو جرام':1000,'كيلو':1000,
 'لتر':1,'ملليلتر':0.001,'كوب':0.24,'نصف كوب':0.12,'ربع كوب':0.06,'ملعقة كبيرة':0.015,'ملعقة صغيرة':0.005,
 'واحدة':1,'بيضة':1,'قطعة':1,'وزنة':1,
 'زجاجة':1,'علبة':1,'ظرف':1,'كيس':1,'عبوة':1,'رشة':1,'نقطة':1
};
function unitBase(u){
 if(u==='جرام'||u==='كيلو جرام'||u==='كيلو')return 'جرام';
 if(['لتر','ملليلتر','كوب','نصف كوب','ربع كوب','ملعقة كبيرة','ملعقة صغيرة'].includes(u))return 'لتر';
 if(u==='واحدة'||u==='بيضة'||u==='قطعة')return 'واحدة';
 return u||'جرام';
}
function factor(u){return UNIT_FACTORS[u]??1}
function norm(q,u){return Number(q||0)*factor(u)}
function compatible(a,b){return unitBase(a)===unitBase(b)}
function migrateUnitName(u){if(u==='كيلو')return 'كيلو جرام';if(u==='قطعة')return 'واحدة';if(!u)return 'جرام';return u}
function migrateStateUnits(data){
 const d=data||{};
 d.recipeNotes=d.recipeNotes&&typeof d.recipeNotes==='object'&&!Array.isArray(d.recipeNotes)?d.recipeNotes:{};
 const convert=(obj,qtyKeys)=>{if(!obj||typeof obj!=='object')return;const old=obj.unit||'';if(old==='ملليلتر'){for(const k of qtyKeys)if(Number.isFinite(Number(obj[k])))obj[k]=Number(obj[k])/1000;obj.unit='لتر'}else obj.unit=migrateUnitName(old)};
 Object.values(d.recipes||{}).forEach(list=>(list||[]).forEach(c=>{if(c.unit==='ملليلتر'){c.qty=Number(c.qty||0)/1000;c.unit='لتر'}else c.unit=migrateUnitName(c.unit)}));
 (d.inventory||[]).forEach(x=>convert(x,['qty']));
 (d.history||[]).forEach(x=>convert(x,['add','deduct','balance']));
 Object.values(d.prices||{}).forEach(x=>{if(x&&x.packUnit==='ملليلتر'){if(Number.isFinite(Number(x.packSize)))x.packSize=Number(x.packSize)/1000;x.packUnit='لتر'}else if(x)x.packUnit=migrateUnitName(x.packUnit)});
 (d.monthlyArchives||[]).forEach(a=>{(a.inventory||[]).forEach(x=>convert(x,['qty']));(a.history||[]).forEach(x=>convert(x,['add','deduct','balance']))});
 return d;
}
function formatAggregate(qty,baseUnit){
 let q=Number(qty)||0;
 if(baseUnit==='لتر'){
  const choices=[['كوب',0.24],['نصف كوب',0.12],['ربع كوب',0.06],['ملعقة كبيرة',0.015],['ملعقة صغيرة',0.005]];
  for(const [u,f] of choices){const n=q/f;if(n>=1&&Math.abs(n-Math.round(n))<1e-7)return {qty:Math.round(n),unit:u}}
  return {qty:q,unit:'لتر'};
 }
 return {qty:q,unit:baseUnit};
}
