function exportCostCsv(){exportCsv('RMY_Recipe_Cost_Report.csv',[['الصنف','تكلفة الخامات للوزنة','التكاليف الإضافية','تكلفة الوزنة','الناتج','تكلفة الوحدة','الهامش المستهدف %','سعر البيع المقترح','خامات بلا سعر'],...names().map(n=>{const r=recipeCost(n);return [n,r.total,r.extra,r.batchCost,r.yieldQty,r.unitCost,r.margin,r.suggested,r.unknown.join('، ')]})])}
function calcSalePreview(){const name=$('saleProduct').value,qty=Number($('saleQty').value),price=Number($('salePrice').value);if(!name||!(qty>0)||!(price>=0)){ $('salePreview').textContent='اختر الصنف وأدخل الكمية والسعر لعرض تقدير الربح.';return}const c=recipeCost(name),revenue=qty*price,cost=qty*c.unitCost,profit=revenue-cost;$('salePreview').innerHTML=`الإيراد المتوقع: <b>${moneyFmt(revenue)} ج.م</b> · تكلفة الخامات التقديرية: <b>${moneyFmt(cost)} ج.م</b> · الفرق قبل المصروفات العامة: <b>${moneyFmt(profit)} ج.م</b>${c.unknown.length?`<div class="danger-note">تنبيه: التكلفة ناقصة لعدم تسعير ${c.unknown.map(esc).join('، ')}.</div>`:''}`}
function addSale(){const name=$('saleProduct').value,qty=Number($('saleQty').value),price=Number($('salePrice').value);if(!name||!Number.isFinite(qty)||qty<=0||!Number.isFinite(price)||price<0){alert('اختر صنفًا وأدخل كمية موجبة وسعر بيع صحيحًا.');return}if(cloudActorRole==='sales'){pmSalesRecord(name,qty,price);return}const c=recipeCost(name);state.salesLog=state.salesLog||[];state.salesLog.unshift({receiptNo:(window.pmIsDrinkName(name)?nextDrinkInvoiceNo():nextInvoiceNo()),group:(window.pmIsDrinkName(name)?'drink':'food'),receiptId:(window.crypto&&crypto.randomUUID?crypto.randomUUID():'m'+Date.now()+Math.random().toString(36).slice(2)),by:cloudActorName||'',at:new Date().toISOString(),date:formatDate(),name,qty,unitPrice:price,revenue:qty*price,unitCostAtSale:c.unitCost===null?null:c.unitCost,costAtSale:c.unitCost===null?null:qty*c.unitCost,unpricedComponents:c.unknown.length,note:$('saleNote').value.trim()});$('saleQty').value='1';$('salePrice').value='';$('saleNote').value='';save();renderSales();alert('تم حفظ عملية البيع. الربح المعروض تقديري وفق أسعار الخامات المسجلة وقت البيع.')}
function addExpense(){const category=$('expenseCategory').value,amount=Number($('expenseAmount').value),note=$('expenseNote').value.trim();if(!Number.isFinite(amount)||amount<=0){alert('أدخل قيمة مصروف أكبر من صفر.');return}state.expensesLog=state.expensesLog||[];state.expensesLog.unshift({date:formatDate(),category,amount,note});$('expenseAmount').value='';$('expenseNote').value='';save();renderSales();alert('تم تسجيل المصروف التشغيلي.')}
function renderSales(){if(!$('salesTable'))return;const sales=state.salesLog||[],expenses=state.expensesLog||[],__mm=monthMetrics({productionLog:state.productionLog||[],salesLog:pmRecostMissing(window.pmCleanSalesForClose?pmCleanSalesForClose(sales):sales),expensesLog:expenses,purchasesLog:state.purchasesLog||[],wasteLog:pmRecostWaste(state.wasteLog||[]),partyInvoices:(window.pmOpenPartyInvoices?window.pmOpenPartyInvoices():[]),history:state.history||[],totalSpent:(state.productionLog||[]).reduce((a,x)=>a+Number(x.totalCost||0),0)}),revenue=__mm.revenue,cost=__mm.salesCost,other=__mm.expenseTotal,profit=__mm.profit,purchases=__mm.purchaseTotal,unknown=(__mm.unknownSales||__mm.wasteUnpriced||__mm.partyUncosted)?1:0;$('financialSummary').innerHTML=`<div class="metric-grid"><div class="metric"><b>${moneyFmt(revenue)} ج.م</b><span>إجمالي المبيعات</span></div><div class="metric"><b>${moneyFmt(cost)} ج.م</b><span>تكلفة الخامات التقديرية</span></div><div class="metric"><b>${moneyFmt(other)} ج.م</b><span>المصروفات التشغيلية</span></div><div class="metric"><b>${moneyFmt(purchases)} ج.م</b><span>مشتريات الخامات (تدفق نقدي وليست مصروف ربح مباشر)</span></div><div class="metric"><b>${moneyFmt(profit)} ج.م</b><span>${__mm.netComplete?'صافي الربح بعد تكلفة المبيعات والحفلات والهالك والمصروفات':'صافي الربح (ناقص '+__mm.uncostedCount+' بند بلا تكلفة)'}</span></div></div>${unknown?`<div class="danger-note">توجد عمليات بيع بدون تكلفة كاملة (خامات غير مسعّرة أو فواتير حفلات بدون تكلفة)؛ صافي الربح غير مكتمل.</div>`:''}<p class="small">هذا ملخص السجلات الحالية فقط. لا يخصم البيع من مخزون الإنتاج تلقائيًا، لأن خصم الخامات يتم من خلال «حساب الطلب» عند تأكيد الإنتاج.</p>`;$('salesTable').innerHTML=sales.length?`<table><tr><th>التاريخ</th><th>الصنف</th><th>الكمية</th><th>سعر الوحدة</th><th>الإيراد</th><th>التكلفة المقدرة</th><th>الفرق</th><th>ملاحظة</th><th>حذف</th></tr>${sales.map((x,i)=>`<tr><td>${esc(x.date)}</td><td>${esc(x.name)}</td><td>${nfmt(x.qty)}</td><td>${moneyFmt(x.unitPrice)} ج.م</td><td>${moneyFmt(x.revenue)} ج.م</td><td>${Number(x.unpricedComponents||0)>0||x.costAtSale==null?'غير مكتملة':moneyFmt(x.costAtSale)+' ج.م'}</td><td>${Number(x.unpricedComponents||0)>0||x.costAtSale==null?'غير مكتمل':moneyFmt(Number(x.revenue||0)-Number(x.costAtSale||0))+' ج.م'}</td><td>${esc(x.note||'')}</td><td><button class="danger mini" onclick="deleteSale(${i})">حذف</button></td></tr>`).join('')}</table>`:'<div class="empty">لا توجد عمليات بيع مسجلة.</div>';$('expensesTable').innerHTML=expenses.length?`<table><tr><th>التاريخ</th><th>البند</th><th>القيمة</th><th>التفاصيل</th><th>حذف</th></tr>${expenses.map((x,i)=>`<tr><td>${esc(x.date)}</td><td>${esc(x.category)}</td><td>${moneyFmt(x.amount)} ج.م</td><td>${esc(x.note||'')}</td><td><button class="danger mini" onclick="deleteExpense(${i})">حذف</button></td></tr>`).join('')}</table>`:'<div class="empty">لا توجد مصروفات مسجلة.</div>';calcSalePreview()}
window.deleteSale=i=>{if(!confirm('حذف عملية البيع هذه؟'))return;state.salesLog.splice(i,1);save();renderSales()};window.deleteExpense=i=>{if(!confirm('حذف المصروف هذا؟'))return;state.expensesLog.splice(i,1);save();renderSales()};
