window.printCurrentMonthReport=()=>{const a={label:$('monthLabel').value.trim()||new Date().toLocaleDateString('ar-EG',{month:'long',year:'numeric'}),closedAt:'تقرير قبل التقفيل',history:clone(state.history||[]),inventory:clone(state.inventory||[]),productionLog:clone(state.productionLog||[]),salesLog:clone(pmRecostMissing(window.pmCleanSalesForClose?pmCleanSalesForClose(state.salesLog||[]):(state.salesLog||[]))),expensesLog:clone(state.expensesLog||[]),purchasesLog:clone(state.purchasesLog||[]),wasteLog:clone(pmRecostWaste(state.wasteLog||[])),stockValue:pmInventoryValue(state.inventory||[]),partyInvoices:clone(window.pmOpenPartyInvoices?window.pmOpenPartyInvoices():[])};a.recipeCount=(a.productionLog||[]).reduce((s,z)=>s+Number(z.recipeCount||0),0);a.totalSpent=(a.productionLog||[]).reduce((s,z)=>s+Number(z.totalCost||0),0);window.pmShowDoc(buildMonthReport(a),'تقرير '+(a.label||'الشهر'))};
window.deleteArchive=async i=>{
 const a=state.monthlyArchives[i];if(!a)return;
 if(!cloudReady||!cloudActorName||!cloudActorPin){alert('لا يمكن حذف أرشيف قبل الاتصال بالسحابة وتسجيل الدخول. الأرشيف لم يتغير.');return}
 if(cloudActorRole==='kitchen'){alert('حساب المطبخ لا يملك صلاحية حذف الأرشيف.');return}
 if(!confirm(`تحذير: أنت على وشك حذف أرشيف «${a.label}» بكل تفاصيله. سننشئ نسخة احتياطية كاملة أولًا. هل تريد المتابعة؟`))return;
 const pw=prompt(`للتأكيد النهائي، اكتب كلمة مرور دخول المدير (الرقم السري) لحذف أرشيف «${a.label}»:`);
 if(!pw){alert('تم إلغاء الحذف؛ لم تتغير البيانات.');return}
 let pwOk=false;
 try{const {data:v,error:ve}=await apiCall({action:'verify_employee',employee_name:cloudActorName,pin:pw});pwOk=!ve&&!!v&&v.ok===true&&v.role==='admin'}catch(_){pwOk=false}
 if(!pwOk){alert('كلمة المرور غير صحيحة أو الحساب ليس مدير. تم إلغاء الحذف؛ لم تتغير البيانات.');return}
 const btn=null;
 try{
  const before=clone(state);const backup=await saveSafetyBackup(before,'قبل حذف أرشيف '+a.label);
  download(`RMY_Backup_Before_Delete_${new Date().toISOString().slice(0,10)}.json`,JSON.stringify({app:'RMY',type:'safety-backup-before-archive-delete',backupId:backup.id,createdAt:new Date(backup.savedAt).toISOString(),state:before},null,2),'application/json;charset=utf-8');
  const next=clone(before);next.monthlyArchives.splice(i,1);
  await persistCloudSnapshot(next);
  const stamp=Date.now();state=next;
  try{localStorage.setItem(KEY,JSON.stringify(next));localStorage.setItem(KEY+'_savedAt',String(stamp))}catch(e){setCloudStatus('أكد الخادم الحذف، لكن تعذر تحديث التخزين المحلي. النسخة الاحتياطية محفوظة.',true)}
  try{await saveCriticalState(next,stamp)}catch(e){setCloudStatus('أكد الخادم الحذف. تعذر تحديث نسخة IndexedDB الحالية، لكن نسخة الأمان السابقة محفوظة.',true)}
  renderAll();renderMonthly();alert('تم حذف الأرشيف بعد تأكيد الخادم. تم إنشاء نسخة أمان محلية وتنزيل نسخة JSON قبل الحذف.');
 }catch(e){alert('لم يتم حذف الأرشيف؛ بقيت البيانات كما هي. سبب المشكلة: '+(e.message||'خطأ غير معروف'))}
 finally{if(btn)btn.disabled=false}
};
window.viewArchive=i=>{const a=state.monthlyArchives[i];if(!a)return;window.pmShowDoc(buildMonthReport(a),'أرشيف: '+(a.label||''))}
