function sheetFromObjects(wb,name,rows){
 const data=rows&&rows.length?rows:[{ملاحظة:'لا توجد بيانات حالياً'}];
 const ws=XLSX.utils.json_to_sheet(data);
 const headers=Object.keys(data[0]||{});
 // Make every worksheet easy to read and edit in Excel: styled headers, filters, frozen header row, useful widths.
 ws['!views']=[{state:'frozen',ySplit:1,topLeftCell:'A2',activePane:'bottomLeft'}];
 if(headers.length && data.length) ws['!autofilter']={ref:XLSX.utils.encode_range({s:{r:0,c:0},e:{r:data.length,c:headers.length-1}})};
 ws['!cols']=headers.map((h,i)=>{let max=String(h).length;for(const row of data)max=Math.max(max,String(row[h]??'').length);return {wch:Math.min(34,Math.max(12,max+3))}});
 ws['!rows']=[{hpt:28},...data.map(()=>({hpt:21}))];
 const range=XLSX.utils.decode_range(ws['!ref']||'A1');
 for(let c=range.s.c;c<=range.e.c;c++){const addr=XLSX.utils.encode_cell({r:0,c});if(ws[addr])ws[addr].s={fill:{fgColor:{rgb:'102A43'}},font:{name:'Arial',sz:12,bold:true,color:{rgb:'FFFFFF'}},alignment:{horizontal:'center',vertical:'center',wrapText:true},border:{bottom:{style:'medium',color:{rgb:'1D4E89'}}}}}
 for(let r=1;r<=range.e.r;r++){for(let c=range.s.c;c<=range.e.c;c++){const addr=XLSX.utils.encode_cell({r,c});if(ws[addr]){const v=ws[addr].v;ws[addr].s={font:{name:'Arial',sz:11,color:{rgb:'172B3A'}},alignment:{vertical:'center',horizontal:typeof v==='number'?'center':'right'},fill:r%2?{fgColor:{rgb:'F2F6FA'}}:{fgColor:{rgb:'FFFFFF'}},border:{bottom:{style:'thin',color:{rgb:'DCE5ED'}}}};if(typeof v==='number')ws[addr].z='#,##0.###'}}}
 ws['!sheetViews']=[{showGridLines:true}];
 XLSX.utils.book_append_sheet(wb,ws,name);
}
