function validateRecoveryState(d){
 if(!d||typeof d!=='object'||!d.recipes||typeof d.recipes!=='object'||Array.isArray(d.recipes)||!Array.isArray(d.inventory)||!Array.isArray(d.history)||!d.prices||typeof d.prices!=='object'||Array.isArray(d.prices))throw Error('invalid-json');
 const check=v=>typeof v==='number'&&Number.isFinite(v)&&v>=0;
 const optionalNonNegative=(obj,keys)=>keys.every(k=>obj[k]===undefined||obj[k]===null||obj[k]===''||check(Number(obj[k])));
 const validHistory=x=>x&&typeof x.name==='string'&&optionalNonNegative(x,['add','deduct','balance']);
 const validInventory=x=>x&&typeof x.name==='string'&&typeof x.unit==='string'&&check(Number(x.qty));
 const validLog=x=>x&&optionalNonNegative(x,['recipeCount','totalCost','unpricedComponents'])&&(x.items===undefined||(Array.isArray(x.items)&&x.items.every(i=>i&&typeof i.name==='string'&&check(Number(i.qty)))));
 if(!Object.values(d.recipes).every(list=>Array.isArray(list)&&list.every(c=>c&&typeof c.name==='string'&&check(Number(c.qty)))))throw Error('invalid-json');
 if(!d.inventory.every(validInventory)||!d.history.every(validHistory))throw Error('invalid-json');
 if(!Object.values(d.prices).every(p=>p&&typeof p==='object'&&optionalNonNegative(p,['purchasePrice','packSize','reorder'])))throw Error('invalid-json');
 if(d.orders!==undefined&&(!Array.isArray(d.orders)||!d.orders.every(x=>x&&typeof x.name==='string'&&check(Number(x.qty)))))throw Error('invalid-json');
 if(d.productionLog!==undefined&&(!Array.isArray(d.productionLog)||!d.productionLog.every(validLog)))throw Error('invalid-json');
 if(d.salesLog!==undefined&&(!Array.isArray(d.salesLog)||!d.salesLog.every(x=>x&&typeof x.name==='string'&&optionalNonNegative(x,['qty','unitPrice','revenue','costAtSale','unitCostAtSale','unpricedComponents']))))throw Error('invalid-json');
 if(d.expensesLog!==undefined&&(!Array.isArray(d.expensesLog)||!d.expensesLog.every(x=>x&&typeof x.category==='string'&&optionalNonNegative(x,['amount']))))throw Error('invalid-json');
 if(d.monthlyArchives!==undefined&&(!Array.isArray(d.monthlyArchives)||!d.monthlyArchives.every(a=>a&&typeof a==='object'&&optionalNonNegative(a,['recipeCount','recipesCount','totalSpent','unpricedComponents'])&&(a.history===undefined||Array.isArray(a.history)&&a.history.every(validHistory))&&(a.inventory===undefined||Array.isArray(a.inventory)&&a.inventory.every(validInventory))&&(a.productionLog===undefined||Array.isArray(a.productionLog)&&a.productionLog.every(validLog))&&(a.salesLog===undefined||Array.isArray(a.salesLog)&&a.salesLog.every(x=>x&&typeof x.name==='string'&&optionalNonNegative(x,['qty','unitPrice','revenue','costAtSale','unitCostAtSale','unpricedComponents'])))&&(a.expensesLog===undefined||Array.isArray(a.expensesLog)&&a.expensesLog.every(x=>x&&typeof x.category==='string'&&optionalNonNegative(x,['amount']))))))throw Error('invalid-json');
 return d
}
